tests.boundary-tests-before-review.zig:
test "cell local fetch trial preserves bounds capacity error order and frames" {
    const Address = enum { frame, last_cell, short_cell, end };
    for ([_]bool{ false, true }) |counted| {
        for ([_]bool{ false, true }) |pending| {
            for ([_]usize{ 0, 1, 2 }) |free| {
                for ([_]Address{ .frame, .last_cell, .short_cell, .end }) |which| {
                    var output = Output{};
                    const machine = try createMachine(&output);
                    defer destroyMachine(machine);
                    machine.keep_counting = counted;
                    try machine.interpretLine(": CELL-READ-PROBE { | x -- } x ;");
                    const id = try machine.lookupOrFail("CELL-READ-PROBE");
                    const word = machine.words[id];
                    var fetch_pc: ?usize = null;
                    for (word.code_start..word.code_end) |pc| {
                        if (machine.code[pc].kind == .local_fetch) fetch_pc = pc;
                    }
                    const pc = fetch_pc orelse return error.TestUnexpectedResult;
                    const locals_before = machine.locals_top;
                    const address: forth.Cell = switch (which) {
                        .frame => locals_before,
                        .last_cell => @intCast(machine.memory.len - 8),
                        .short_cell => @intCast(machine.memory.len - 7),
                        .end => @intCast(machine.memory.len),
                    };
                    machine.code[pc].value = address - locals_before;
                    if (which == .last_cell) try machine.writeCell(address, 1234567);
                    const depth = machine.data_stack.len - free;
                    @memset(machine.data_stack, -37);
                    machine.data_depth = depth;
                    machine.return_stack[0] = 41;
                    machine.return_stack[1] = 42;
                    machine.return_depth = 2;
                    machine.float_stack[0] = 1.5;
                    machine.float_depth = 1;
                    machine.output_error = if (pending) -88 else null;
                    const invalid = which == .short_cell or which == .end;
                    if (invalid) {
                        try std.testing.expectError(error.InvalidAddress, machine.executeWord(id));
                    } else if (free == 0) {
                        try std.testing.expectError(error.StackOverflow, machine.executeWord(id));
                    } else {
                        try machine.executeWord(id);
                    }
                    const success = !invalid and free != 0;
                    try std.testing.expectEqual(depth + @intFromBool(success), machine.data_depth);
                    for (machine.data_stack[0..depth]) |value| try std.testing.expectEqual(@as(forth.Cell, -37), value);
                    if (success) try std.testing.expectEqual(@as(forth.Cell, if (which == .last_cell) 1234567 else 0), machine.data_stack[depth]);
                    try std.testing.expectEqual(@as(usize, 2), machine.return_depth);
                    try std.testing.expectEqualSlices(forth.Cell, &.{ 41, 42 }, machine.return_stack[0..2]);
                    try std.testing.expectEqual(@as(usize, 1), machine.float_depth);
                    try std.testing.expectEqual(@as(forth.Float, 1.5), machine.float_stack[0]);
                    try std.testing.expectEqual(locals_before, machine.locals_top);
                    try std.testing.expectEqual(@as(usize, 0), machine.frame_depth);
                    try std.testing.expectEqual(@as(usize, 0), machine.call_depth);
                    try std.testing.expectEqual(@as(usize, 0), machine.catch_depth);
                    try std.testing.expectEqual(@as(?forth.Cell, if (pending) -88 else null), machine.output_error);
                    if (!success and @import("../core/defs.zig").debug_enabled) {
                        try std.testing.expectEqual(@as(u16, @intCast(pc + 1)), machine.failed_pc);
                    }
                }
            }
        }
    }
}

test "cell local fetch trial rejects missing locals frame without consuming stack" {
    for ([_]bool{ false, true }) |counted| {
        var output = Output{};
        const machine = try createMachine(&output);
        defer destroyMachine(machine);
        machine.keep_counting = counted;
        try machine.interpretLine(": FRAMELESS-READ-PROBE 0 ;");
        const id = try machine.lookupOrFail("FRAMELESS-READ-PROBE");
        const pc = machine.words[id].code_start;
        machine.code[pc] = .{ .kind = .local_fetch, .value = 0 };
        try machine.push(91);
        const locals_before = machine.locals_top;
        try std.testing.expectError(error.InvalidAddress, machine.executeWord(id));
        try expectStack(machine, &.{91});
        try std.testing.expectEqual(locals_before, machine.locals_top);
        try std.testing.expectEqual(@as(usize, 0), machine.frame_depth);
        try std.testing.expectEqual(@as(usize, 0), machine.call_depth);
        if (@import("../core/defs.zig").debug_enabled) try std.testing.expectEqual(pc + 1, machine.failed_pc);
    }
}

