tests.fallback-tests.zig:
test "cell local fetch trial retains typed fallback boundary semantics" {
    const LocalKind = @import("../core/defs.zig").LocalKind;
    for ([_]LocalKind{ .char, .xt, .double, .float }) |kind| {
        if (kind == .float and !@import("../core/defs.zig").float_enabled) continue;
        for ([_]bool{ false, true }) |counted| {
            for ([_]bool{ false, true }) |pending| {
                for ([_]usize{ 0, 1, 2 }) |free| {
                    for ([_]usize{ 0, 1 }) |float_free| {
                        for (0..3) |point| {
                            var output = Output{};
                            const machine = try createMachine(&output);
                            defer destroyMachine(machine);
                            machine.keep_counting = counted;
                            try machine.interpretLine(": TYPED-READ-PROBE { | x -- } x ;");
                            const id = try machine.lookupOrFail("TYPED-READ-PROBE");
                            const word = machine.words[id];
                            var found: ?usize = null;
                            for (word.code_start..word.code_end) |pc| {
                                if (machine.code[pc].kind == .local_fetch) found = pc;
                            }
                            const pc = found orelse return error.TestUnexpectedResult;
                            const width: usize = if (kind == .double) 16 else if (kind == .char) 1 else 8;
                            const address: forth.Cell = @intCast(machine.memory.len - (if (point == 0) width else if (point == 1) @as(usize, 7) else 0));
                            const invalid = point == 2 or (point == 1 and kind != .char);
                            const locals_before = machine.locals_top;
                            machine.code[pc].value = (@as(forth.Cell, @intFromEnum(kind)) << 32) | (address - locals_before);
                            if (!invalid) switch (kind) {
                                .char => machine.memory[@intCast(address)] = 171,
                                .xt => try machine.writeCell(address, 731),
                                .double => try machine.writeDouble(address, (@as(forth.Double, 0x44556677) << 64) | 0x11223344),
                                .float => try machine.writeFloat(address, 2.5),
                                else => unreachable,
                            };
                            const depth = machine.data_stack.len - free;
                            const fdepth = machine.float_stack.len - float_free;
                            @memset(machine.data_stack, -37);
                            @memset(machine.float_stack, -3.0);
                            machine.data_depth = depth;
                            machine.float_depth = fdepth;
                            machine.return_depth = 2;
                            machine.return_stack[0] = 41;
                            machine.return_stack[1] = 42;
                            machine.output_error = if (pending) -88 else null;
                            const overflow = if (kind == .float) float_free == 0 else free < (if (kind == .double) @as(usize, 2) else 1);
                            if (invalid) {
                                try std.testing.expectError(error.InvalidAddress, machine.executeWord(id));
                            } else if (overflow) {
                                if (kind == .float) try std.testing.expectError(error.FloatStackOverflow, machine.executeWord(id)) else try std.testing.expectError(error.StackOverflow, machine.executeWord(id));
                            } else try machine.executeWord(id);
                            const added: usize = if (invalid or kind == .float) 0 else @min(free, if (kind == .double) @as(usize, 2) else 1);
                            const fadded: usize = @intFromBool(!invalid and kind == .float and float_free != 0);
                            try std.testing.expectEqual(depth + added, machine.data_depth);
                            try std.testing.expectEqual(fdepth + fadded, machine.float_depth);
                            for (machine.data_stack[0..depth]) |value| try std.testing.expectEqual(@as(forth.Cell, -37), value);
                            for (machine.data_stack[depth + added ..]) |value| try std.testing.expectEqual(@as(forth.Cell, -37), value);
                            if (added != 0) try std.testing.expectEqual(@as(forth.Cell, if (kind == .double) 0x11223344 else if (kind == .char) 171 else 731), machine.data_stack[depth]);
                            if (added == 2) try std.testing.expectEqual(@as(forth.Cell, 0x44556677), machine.data_stack[depth + 1]);
                            for (machine.float_stack[0..fdepth]) |value| try std.testing.expectEqual(@as(forth.Float, -3.0), value);
                            if (fadded != 0) try std.testing.expectEqual(@as(forth.Float, 2.5), machine.float_stack[fdepth]);
                            for (machine.float_stack[fdepth + fadded ..]) |value| try std.testing.expectEqual(@as(forth.Float, -3.0), value);
                            try std.testing.expectEqualSlices(forth.Cell, &.{ 41, 42 }, machine.return_stack[0..2]);
                            try std.testing.expectEqual(@as(usize, 2), machine.return_depth);
                            try std.testing.expectEqual(locals_before, machine.locals_top);
                            try std.testing.expectEqual(@as(usize, 0), machine.frame_depth);
                            try std.testing.expectEqual(@as(usize, 0), machine.call_depth);
                            try std.testing.expectEqual(@as(usize, 0), machine.catch_depth);
                            try std.testing.expectEqual(@as(?forth.Cell, if (pending) -88 else null), machine.output_error);
                            if ((invalid or overflow) and @import("../core/defs.zig").debug_enabled) try std.testing.expectEqual(@as(u16, @intCast(pc + 1)), machine.failed_pc);
                        }
                    }
                }
            }
        }
    }
}

test "cell local fetch trial overflow under nested CATCH restores locals and continues" {
    for ([_]bool{ false, true }) |counted| {
        var output = Output{};
        const machine = try createMachine(&output);
        defer destroyMachine(machine);
        machine.keep_counting = counted;
        const locals_before = machine.locals_top;
        try machine.interpretLine(": LOCAL-FULL { | x -- } S\" STACK-CELLS\" ENVIRONMENT? DROP 0 DO 0 LOOP x ; : LOCAL-NEST LOCAL-FULL ; : LOCAL-NEXT { a b -- } a b - ; ' LOCAL-NEST CATCH");
        try expectStack(machine, &.{-3});
        try std.testing.expectEqual(locals_before, machine.locals_top);
        try std.testing.expectEqual(@as(usize, 0), machine.frame_depth);
        try std.testing.expectEqual(@as(usize, 0), machine.call_depth);
        try std.testing.expectEqual(@as(usize, 0), machine.catch_depth);
        try machine.interpretLine("10 3 LOCAL-NEXT");
        try expectStack(machine, &.{ -3, 7 });
        try std.testing.expectEqual(locals_before, machine.locals_top);
    }
}

